<?php
 namespace Pterodactyl\Models\Dezerx; use Pterodactyl\Models\User; use Pterodactyl\Models\Server; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo; class DiscordBotAlert extends Model { protected $table = 'dezerx_discord_bot_alerts'; protected $guarded = ['id']; protected $casts = [ 'bot_id' => 'int', 'user_id' => 'int', 'server_id' => 'int', 'cpu' => 'int', 'memory' => 'int', 'disk' => 'int', 'offline' => 'bool', 'cooldown' => 'int', 'state' => 'array', 'notified_at' => 'immutable_datetime', 'checked_at' => 'immutable_datetime', ]; public function bot(): BelongsTo { return $this->belongsTo(DiscordBot::class, 'bot_id'); } public function user(): BelongsTo { return $this->belongsTo(User::class, 'user_id'); } public function server(): BelongsTo { return $this->belongsTo(Server::class, 'server_id'); } public function watches(): array { return array_filter([ 'cpu' => $this->cpu, 'memory' => $this->memory, 'disk' => $this->disk, ], fn (?int $value) => $value !== null && $value > 0); } } 